style.css:
/* Efecto de entrada suave y destello para todas las páginas */
body {
    animation: introEfecto 0.8s ease-out forwards;
}

@keyframes introEfecto {
    0% {
        opacity: 0;
        filter: blur(10px) brightness(2);
        transform: scale(0.99);
    }
    50% {
        filter: blur(3px) brightness(1.3);
    }
    100% {
        opacity: 1;
        filter: blur(0px) brightness(1);
        transform: scale(1);
    }
}
